component_data_script:
raw_rows = props.get("steps") or []
if isinstance(raw_rows, str):
	try:
		raw_rows = json.loads(raw_rows)
	except Exception:
		raw_rows = [line for line in raw_rows.split("\n") if line.strip()]
if not isinstance(raw_rows, list):
	raw_rows = []
rows = []
for raw in raw_rows:
	try:
		parts = [part.strip() for part in str(raw).split("|")]
		while len(parts) < 3:
			parts.append("")
		if parts[0] or parts[1]:
			rows.append(parts)
	except Exception:
		continue

records = []
for parts in rows:
	records.append({"title": parts[0], "detail": parts[1], "length": parts[2], "has_length": len(parts[2]) > 0})
component.steps = records
